python3 -c "
from math import gcd
from functools import reduce

def P(n):
    return n*n+n+1

def prime_factors(n):
    if n<=1: return set()
    f=set()
    d=2
    while d*d<=n:
        while n%d==0:
            f.add(d); n//=d
        d+=1
    if n>1: f.add(n)
    return f

def is_fragrant(vals):
    if len(vals)<2: return False
    pf=[prime_factors(v) for v in vals]
    for i in range(len(vals)):
        ok=False
        for j in range(len(vals)):
            if i!=j and pf[i]&pf[j]:
                ok=True; break
        if not ok: return False
    return True

# search for minimal b
for b in range(2,20):
    found=False
    for a in range(0,20000):
        vals=[P(a+k) for k in range(1,b+1)]
        if is_fragrant(vals):
            print(f'b={b}, a={a}, vals={vals}')
            found=True
            break
    if found:
        print(f'Minimal b = {b}')
        break
    else:
        print(f'b={b}: not found in range')
"

